  Future<void> _endDate(BuildContext context) async {
    final DateTime? picked = await showDatePicker(
      context: context,
      initialDate: enddate ?? DateTime.now(),
      firstDate: DateTime(2015, 8),
      lastDate: DateTime(2101),
    );
    if (picked != null && picked != enddate) {
      setState(() {
        enddate = picked;
        enddateController.text = DateFormat('yyyy-MM-dd').format(picked);
      });
    }
  }

  // Helper function to convert display format back to API format (yyyy-MM-dd)
  String _convertToApiFormat(String displayDate) {
    if (displayDate.isEmpty) return "";
    try {
      DateTime? parsedDate;

      // Try to parse the date using common formats
      List<String> dateFormats = [
        'yyyy-MM-dd',
        'yyyy-MMM-dd',
        'MM/dd/yyyy',
        'MM-dd-yyyy',
        'dd/MM/yyyy',
        'dd-MM-yyyy'
      ];

      for (String format in dateFormats) {
        try {
          parsedDate = DateFormat(format).parse(displayDate);
          break;
        } catch (e) {
          continue;
        }
      }

      if (parsedDate != null) {
        return DateFormat('yyyy-MM-dd').format(parsedDate);
      }

      return displayDate; // Return as is if parsing fails
    } catch (e) {
      return displayDate; // Return as is if parsing fails
    }
  }

  Future<void> fetchPropertySummeryData(String rentalId) async {
    setState(() {
      isLoaders = true;
    });
    SharedPreferences prefs = await SharedPreferences.getInstance();
    //String? id = prefs.getString("rentalid");
    String? adminid = prefs.getString("adminId");
    String? id = prefs.getString("staff_id");
    String? token = prefs.getString('token');
    final response = await apiGet(
        Uri.parse('$Api_url/api/rentals/rental_summary/$rentalId'),
        headers: {
          "authorization": "CRM $token",
          "id": "CRM $id",
        });
    log("$Api_url/api/rentals/rental_summary/$rentalId ${response.body}");
    if (response.statusCode == 200) {
      // Parse the response body
      final Map<String, dynamic> data = json.decode(response.body);
      List resData = data['data'];
      // Extract the rental data from the response
      final rentalData = Rentals.fromJson(resData.first);

      setState(() {
        widget.properties = rentalData;
        isLoaders = false;
      });
    } else {
      throw Exception('Failed to load count data');
    }
  }

  /// Required by [NetworkRetryState]: re-issue this screen's own load.
  /// The data calls from `initState` only — the tab controllers and
  /// scroll listener it also sets up must not be rebuilt on a reload.
  @override
  Future<void> reloadData() async {
    if (!mounted) return;
    _fetchData();
    setState(() {
      futureUnitsummery =
          Properies_summery_Repo().fetchunit(widget.properties.rentalId ?? "");
      futurePropertysummery = Properies_summery_Repo()
          .fetchPropertiessummery(widget.properties.rentalId!);
      futureworkordersummery =
          Properies_summery_Repo().fetchWorkOrders(widget.properties.rentalId!);
    });
    fetchunits1();
  }

  @override
  void initState() {
    super.initState();
    _connectivitySub = Connectivity().onConnectivityChanged.listen((ConnectivityResult result) {
      if (!mounted) return;
      // The event is only a trigger: checkInternet() verifies
      // against the network before deciding, so a stale `none`
      // from the plugin cannot strand this screen offline.
      checkInternet();
    });
    if (widget.notification_redirect != null &&
        widget.notification_redirect == true) {
      fetchPropertySummeryData(widget.properties.rentalId!);
    }
    checkInternet();
    futureUnitsummery =
        Properies_summery_Repo().fetchunit(widget.properties.rentalId!);

    futurePropertysummery = Properies_summery_Repo()
        .fetchPropertiessummery(widget.properties.rentalId!);
    futureworkordersummery =
        Properies_summery_Repo().fetchWorkOrders(widget.properties.rentalId!);
    // futuresummery = Properies_summery_Repo().fetchPropertiessummery(widget.properties.rentalId!);
    _tabController = TabController(length: 5, vsync: this);
    _taxInsuranceTabController = TabController(length: 3, vsync: this);
    _additionalStatsTabController = TabController(length: 3, vsync: this);
    // street3.text = widget.unit!.rentalunitadress!;
    futureRentalDetails = Properies_summery_Repo()
        .fetchrentalDetails(widget.properties.rentalId!);
    futureSummaryWithFinancial = _loadSummaryWithFinancial();
    // futureLeaseDetails = Properies_summery_Repo().fetchrLeaseDetails(widget.unit?.unitId ?? "");
    futureUnitsummery.then((units) {
      if (units.isNotEmpty) {
        final String unitId = units.first.unitId!;
        setState(() {
          futureLeaseDetails =
              Properies_summery_Repo().fetchrLeaseDetails(unitId);
          _summaryLeasesFuture =
              Properies_summery_Repo().fetchrLeaseDetails(unitId);
        });
      }
    });
    futureUnitsummery.then((units) {
      if (units.isNotEmpty) {
        // Get the first unit's ID and fetch lease details
        String unitId = units.first.unitId!;
        futureLeaseRevenueDetails =
            Properies_summery_Repo().fetchrRevenueDetails(unitId);
      }
    });
    _fetchData();
    // moveOutDate = DateFormat('dd-MM-yyyy').format(DateTime.now());
    futurerentalowners = PropertiesRepository().fetchProperties();
    futurePropertyTaxes = _fetchPropertyTaxes();

//     displayDate = DateFormat('dd-MM-yyyy').format(DateTime.parse(moveOutDate));
// startdateController.text = displayDate;
    fetchunits1();
    //fetchLeases();
    // fetchAndSetCounts(context);
    //workorder
    // fetchAndSetCounts(context);
    WidgetsBinding.instance.addPostFrameCallback((_) {});
  }

