    if (oldWidget.properties.rentalId != widget.properties.rentalId) {
      _propertyValuesRentalOverride = null;
      _purchaseInfoRentalOverride = null;
    }
  }

  /// Returns asset path for property summary tab icon (lease-style dropdown).
  String _getPropertyTabIconPath(String title) {
    if (title.startsWith('Summary')) return 'assets/icons/summery.png';
    if (title.startsWith('Unit')) return 'assets/icons/renter.png';
    if (title.startsWith('Tenant')) return 'assets/icons/tenants.png';
    if (title.startsWith('Work order')) return 'assets/icons/maintence.png';
    if (title.startsWith('Lease')) return 'assets/icons/document.png';
    if (title.startsWith('Revenue')) return 'assets/icons/financial.png';
    if (title.startsWith('Annual Expenses'))
      return 'assets/icons/Taxes.png';
    if (title.startsWith('Utilities')) return 'assets/icons/uti.png';
    if (title.startsWith('Additional Stats')) return 'assets/icons/additional.png';
    return 'assets/icons/summery.png';
  }

  ConnectivityResult? _connectivityResult;
  StreamSubscription<ConnectivityResult>? _connectivitySub;
  void checkInternet() async {
    var connectiondata = await Connectivity().checkConnectivity();
    // connectivity_plus answers from a cached reachability result that
    // can stay `none` after the connection is back (reliably so on the
    // iOS simulator), which made this screen declare itself offline
    // while requests actually succeed. Confirm before believing it.
    if (connectiondata == ConnectivityResult.none &&
        await hasNetworkNow()) {
      connectiondata = ConnectivityResult.wifi;
    }
    if (!mounted) return;
    setState(() {
      _connectivityResult = connectiondata;
    });
  }

  Future<List<Map<String, dynamic>>> _fetchPropertyTaxes() async {
    try {
      SharedPreferences prefs = await SharedPreferences.getInstance();
      String? token = prefs.getString('token');
      String? staffid = prefs.getString("staff_id");

      final response = await apiGet(
        Uri.parse('${Api_url}/api/taxes/${widget.properties.rentalId}'),
        headers: {
          'Content-Type': 'application/json',
          'authorization': 'CRM $token',
          'id': 'CRM $staffid',
        },
      ).timeout(const Duration(seconds: 30));

      if (response.statusCode == 200) {
        final data = json.decode(response.body);
        if (data['success'] == true && data['data'] != null) {
          return List<Map<String, dynamic>>.from(data['data']);
        }
      }
      return [];
    } catch (e) {
      logError('Error loading property taxes: $e');
      return [];
    }
  }

  Future<Map<String, dynamic>?> _fetchFinancialSummary() async {
    try {
      SharedPreferences prefs = await SharedPreferences.getInstance();
      String? token = prefs.getString('token');
      String? staffid = prefs.getString("staff_id");
      final response = await apiGet(
        Uri.parse(
            '${Api_url}/api/mortgage/${widget.properties.rentalId}/financial-summary'),
        headers: {
          'Content-Type': 'application/json',
          'authorization': 'CRM $token',
          'id': 'CRM $staffid',
        },
      ).timeout(const Duration(seconds: 30));
      if (response.statusCode == 200) {
        final data = json.decode(response.body);
        if (data['success'] == true && data['data'] != null) {
          return Map<String, dynamic>.from(data['data']);
        }
      }
      return null;
    } catch (e) {
      logError('Error loading financial summary: $e');
      return null;
    }
  }

  Future<(Rentals, Map<String, dynamic>?)> _loadSummaryWithFinancial() async {
    final rental = await futureRentalDetails;
    final financial = await _fetchFinancialSummary();
    return (rental, financial);
  }

  static const int _galleryPreviewCount = 4;

  Widget _buildGallerySection(BuildContext context, Rentals rentalDetails) {
    final rentalId = rentalDetails.rentalId ?? widget.properties.rentalId ?? '';
    if (rentalId.isEmpty) return const SizedBox.shrink();
    return Container(
      decoration: BoxDecoration(
        color: Colors.white,
        border: Border.all(color: const Color(0xFFDEE2E6), width: 1),
        borderRadius: BorderRadius.circular(10),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withOpacity(0.06),
            blurRadius: 8,
            offset: const Offset(0, 2),
          ),
        ],
      ),
      child: Padding(
        padding: const EdgeInsets.fromLTRB(16, 10, 16, 10),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          mainAxisSize: MainAxisSize.min,
          children: [
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Text(
                  'Gallery',
                  style: TextStyle(
                    color: blueColor,
                    fontSize: MediaQuery.of(context).size.width < 500 ? 16 : 20,
                    fontWeight: FontWeight.bold,
                  ),
                ),
                ElevatedButton(
                  style: ElevatedButton.styleFrom(
                    backgroundColor: blueColor,
                    foregroundColor: Colors.white,
                    padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
                  ),
                  onPressed: () {
                    Navigator.push(
                      context,
                      MaterialPageRoute(
                        builder: (ctx) => AddPhotoScreen(
                          rentalId: rentalId,
                          onAdded: () => setState(() => _galleryRefreshKey++),
                        ),
                      ),
                    ).then((_) => setState(() => _galleryRefreshKey++));
                  },
                  child: const Text('Add Photo',style: TextStyle(fontSize: 15, fontWeight: FontWeight.bold),),
                ),
              ],
            ),
            const SizedBox(height: 12),
            FutureBuilder<GalleryResponse>(
              key: ValueKey('gallery_${rentalId}_$_galleryRefreshKey'),
              future: GalleryService.getGallery(rentalId),
              builder: (context, snapshot) {
                if (snapshot.connectionState == ConnectionState.waiting) {
                  return Padding(
                    padding: const EdgeInsets.symmetric(vertical: 16),
                    child: Center(
                      child: SpinKitFadingCircle(color: blueColor, size: 36),
                    ),
                  );
                }
                if (snapshot.hasError || !snapshot.hasData) {
                  return const SizedBox.shrink();
                }
                final response = snapshot.data!;
                final photos = response.photos;
                if (photos.isEmpty) {
                  return Padding(
                    padding: const EdgeInsets.symmetric(vertical: 28, horizontal: 8),
                    child: Center(
                      child: Text(
                        "No photos in gallery. Click 'Add Photo' to get started.",
                        textAlign: TextAlign.center,
                        style: TextStyle(
                          color: Colors.grey[600],
                          fontSize: 14,
                          height: 1.4,
                        ),
                      ),
                    ),
                  );
                }
                final showCount = _galleryViewMore ? photos.length : _galleryPreviewCount.clamp(0, photos.length);
                final displayPhotos = photos.take(showCount).toList();
                final hasMore = photos.length > _galleryPreviewCount;
                return Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    GridView.builder(
                      shrinkWrap: true,
                      physics: const NeverScrollableScrollPhysics(),
                      gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
                        crossAxisCount: MediaQuery.of(context).size.width < 500 ? 2 : 4,
                        crossAxisSpacing: 8,
                        mainAxisSpacing: 8,
                        childAspectRatio: 1,
                      ),
                      itemCount: displayPhotos.length,
                      itemBuilder: (context, index) {
                        final photo = displayPhotos[index];
                        final imageUrl = photo.image.startsWith('http')
                            ? photo.image
                            : '$image_url${photo.image}';
                        return Container(
                          decoration: BoxDecoration(
                            borderRadius: BorderRadius.circular(8),
                            border: photo.isCover
                                ? Border.all(color: blueColor, width: 3)
                                : null,
                            boxShadow: photo.isCover
                                ? [BoxShadow(color: blueColor.withOpacity(0.3), blurRadius: 4, offset: const Offset(0, 1))]
                                : null,
                          ),
                          child: ClipRRect(
                            borderRadius: BorderRadius.circular(8),
                            child: Stack(
                              fit: StackFit.expand,
                              children: [
                                GestureDetector(
                                  onTap: () {
                                    Navigator.push(
                                      context,
                                      MaterialPageRoute(
                                        builder: (ctx) => PhotoPreviewScreen(imageUrl: imageUrl),
                                      ),
                                    );
                                  },
                                  child: CachedNetworkImage(
                                    imageUrl: imageUrl,
                                    fit: BoxFit.cover,
                                    placeholder: (_, __) => Container(
                                      color: Colors.grey[200],
                                      child: Center(child: SpinKitFadingCircle(color: blueColor, size: 32)),
                                    ),
                                    errorWidget: (_, __, ___) => const Icon(Icons.broken_image, size: 32),
                                  ),
                                ),
                                if (photo.isCover)
                                  Positioned(
                                    top: 4,
                                    left: 4,
                                    child: Container(
                                      padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
                                      decoration: BoxDecoration(
                                        color: blueColor,
                                        borderRadius: BorderRadius.circular(4),
                                      ),
                                      child: const Text(
                                        'COVER',
                                        style: TextStyle(
                                          color: Colors.white,
                                          fontWeight: FontWeight.bold,
                                          fontSize: 9,
                                        ),
                                      ),
                                    ),
                                  ),
                                Positioned(
                                  top: 4,
                                  right: 4,
                                  child: Row(
                                    mainAxisSize: MainAxisSize.min,
                                    children: [
                                      _galleryActionIcon(
                                        context,
                                        FontAwesomeIcons.pen,
                                        Colors.green,
                                        const Color(0xFFE8F5E9),
                                        () async {
                                      final updated = await Navigator.push<bool>(
                                        context,
                                        MaterialPageRoute(
                                          builder: (ctx) => EditPhotoScreen(
                                            rentalId: rentalId,
                                            photo: photo,
                                            onSaved: () => setState(() => _galleryRefreshKey++),
                                          ),
                                        ),
                                      );
                                      if (updated == true && mounted) setState(() => _galleryRefreshKey++);
                                    },
                                  ),
                                  const SizedBox(width: 4),
                                      _galleryActionIcon(
                                        context,
                                        FontAwesomeIcons.trashCan,
                                        Colors.red,
                                        const Color(0xFFFFEBEE),
                                        () async {
                                          final confirm = await _showGalleryDeleteDialog(context);
                                          if (confirm != true) return;
                                          try {
                                            await GalleryService.deletePhoto(rentalId, photo.id);
                                            if (mounted) {
                                              Fluttertoast.showToast(msg: 'Photo deleted');
                                              setState(() => _galleryRefreshKey++);
                                            }
                                          } catch (e) {
                                            if (mounted) Fluttertoast.showToast(msg: 'Failed to delete: ${friendlyErrorMessage(e)}');
                                          }
                                        },
                                      ),
                                    ],
                                  ),
                                ),
                                if (photo.description.isNotEmpty)
                                  Positioned(
                                    left: 0,
                                    right: 0,
                                    bottom: 0,
                                    child: Container(
                                      padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 4),
                                      decoration: BoxDecoration(
                                        gradient: LinearGradient(
                                          begin: Alignment.bottomCenter,
                                          end: Alignment.topCenter,
                                          colors: [Colors.black54, Colors.transparent],
                                        ),
                                      ),
                                      child: Text(
                                        photo.description,
                                        maxLines: 1,
                                        overflow: TextOverflow.ellipsis,
                                        style: const TextStyle(color: Colors.white, fontSize: 10, fontWeight: FontWeight.bold),
                                      ),
                                    ),
                                  ),
                                if (!photo.isCover)
                                  Positioned(
                                    bottom: 4,
                                    right: 4,
                                    child: _galleryStarButton(
                                      context,
                                      () async {
                                        try {
                                          await GalleryService.setCover(rentalId, photo.id);
                                          if (mounted) {
                                            Fluttertoast.showToast(msg: 'Cover photo set');
                                            setState(() => _galleryRefreshKey++);
                                          }
                                        } catch (e) {
