  Widget _noiRow(String label, num value, double bodySize,
      {String? leadingIconAsset}) {
    final isNegative = value < 0;
    final display = (isNegative ? '-' : '') +
        NumberFormat.currency(symbol: '\$', decimalDigits: 2)
            .format(value.abs());
    // Web parity: the label sits on its own line with the amount stacked
    // underneath, so however long the figure is it wraps naturally at full
    // size instead of being squeezed against the right edge.
    return Padding(
      padding: const EdgeInsets.only(bottom: 12.0),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              if (leadingIconAsset != null) ...[
                Image.asset(leadingIconAsset, width: 20, height: 20),
                const SizedBox(width: 8),
              ],
              Flexible(
                child: Text(label,
                    style: TextStyle(
                        fontSize: bodySize,
                        color: Colors.grey[700],
                        fontWeight: FontWeight.w500)),
              ),
            ],
          ),
          const SizedBox(height: 2),
          Text(display,
              softWrap: true,
              style: TextStyle(
                  fontSize: bodySize,
                  color: blueColor,
                  fontWeight: FontWeight.bold)),
        ],
      ),
    );
  }

  String _formatDate(String dateString) {
    try {
      DateTime date = DateTime.parse(dateString);
      return DateFormat('yyyy-MM-dd').format(date);
    } catch (e) {
      return dateString; // Return original string if parsing fails
    }
  }

