    } else if (sorting2) {
      data.sort((a, b) => ascending2
          ? a.status!.compareTo(b.status!)
          : b.status!.compareTo(a.status!));
    } else if (sorting3) {
      data.sort((a, b) => ascending3
          ? a.createdAt!.compareTo(b.createdAt!)
          : b.createdAt!.compareTo(a.createdAt!));
    }
  }

