  Tenants(BuildContext context) {
    return LayoutBuilder(
      builder: (context, constraints) {
        bool isTablet = constraints.maxWidth > 600;

        return FutureBuilder<List<TenantData>>(
          future: Properies_summery_Repo()
              .fetchPropertiessummery(widget.properties.rentalId!),
          builder: (context, snapshot) {
            if (snapshot.connectionState == ConnectionState.waiting) {
              return const Center(
                child: SpinKitFadingCircle(
                  color: Colors.black,
                  size: 40.0,
                ),
              );
            } else if (snapshot.hasError) {
              return Text(friendlyErrorMessage(snapshot.error), textAlign: TextAlign.center);
            } else {
              List<TenantData> tenants = snapshot.data ?? [];
              if (snapshot.data!.length == 0) {
                return Container(
                  height: MediaQuery.of(context).size.height * .5,
                  child: Center(
                    child: Column(
                      mainAxisAlignment: MainAxisAlignment.center,
                      crossAxisAlignment: CrossAxisAlignment.center,
                      children: [
                        Image.asset(
                          "assets/images/no_data.jpg",
                          height: 200,
                          width: 200,
                        ),
                        const SizedBox(
                          height: 10,
                        ),
                        Text(
                          "No Data Available",
                          style: TextStyle(
                              fontWeight: FontWeight.bold,
                              color: blueColor,
                              fontSize: 16),
                        )
                      ],
                    ),
                  ),
                );
              }
              return isTablet
                  ? SingleChildScrollView(
                      scrollDirection: Axis.vertical,
                      child: Padding(
                        padding: const EdgeInsets.only(
                          left: 35,
                          right: 35,
                          top: 30,
                        ),
                        child: Wrap(
                          alignment: WrapAlignment.start,
                          spacing: MediaQuery.of(context).size.width * 0.03,
                          runSpacing: MediaQuery.of(context).size.width * 0.035,
                          children: List.generate(
                            tenants.length,
                            (index) => Container(
                              height: 245,
                              width: MediaQuery.of(context).size.width * .44,
                              decoration: BoxDecoration(
                                color: Colors.white,
                                borderRadius: BorderRadius.circular(16),
                                border: Border.all(color: borderClr),
                              ),
                              child: buildTenantCard(tenants[index]),
                            ),
                          ),
                        ),
                      ),
                    )
                  : SingleChildScrollView(
                      scrollDirection: Axis.vertical,
                      child: Column(
                        children: [
                          Wrap(
                            alignment: WrapAlignment.start,
                            spacing: MediaQuery.of(context).size.width * 0.03,
                            runSpacing:
                                MediaQuery.of(context).size.width * 0.02,
                            children: List.generate(tenants.length, (index) {
                              DateTime currentDate = DateTime.now();
                              DateTime moveoutDate;
                              bool? ismove = false;

                              if (snapshot.data![index].moveoutDate != null &&
                                  snapshot.data![index].moveoutDate! != "") {
                                moveoutDate = DateFormat('yyyy-MM-dd')
                                    .parse(snapshot.data![index].moveoutDate!);
                                ismove =
                                    moveoutDate.difference(currentDate).inDays <
                                        1;
                              }
                              return Padding(
                                padding: const EdgeInsets.only(
                                  left: 20,
                                  right: 20,
                                  top: 20,
                                ),
                                child: Container(
                                    decoration: BoxDecoration(
                                      color: Colors.white,
                                      borderRadius: BorderRadius.circular(16),
                                      border: Border.all(color: borderClr),
                                    ),
                                    child: buildTenantCard(tenants[index],
                                        tenants: tenants,
                                        isMoveouts: (snapshot
                                                    .data![index].moveoutDate ==
                                                "")
                                            ? false
                                            : (snapshot.data![index]
                                                        .moveoutDate !=
                                                    "")
                                                ? true
                                                : false),
                                  ),
                              );
                            }),
                          ),
                          const SizedBox(
                            height: 20,
                          ),
                        ],
                      ),
                    );
            }
          },
        );
      },
    );
  }

  Widget buildTenantCard(TenantData tenant,
      {bool? isMoveouts, List<TenantData>? tenants}) {
    final dateProvider = Provider.of<DateProvider>(context);
    final fn = '${tenant.firstName ?? ''}'.trim();
    final ln = '${tenant.lastName ?? ''}'.trim();
    final initials = ((fn.isNotEmpty ? fn[0] : '') +
            (ln.isNotEmpty ? ln[0] : ''))
        .toUpperCase();
    return Padding(
      padding: const EdgeInsets.all(16.0),
      child: Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Row(
          crossAxisAlignment: CrossAxisAlignment.center,
          children: [
            Container(
              height: 48,
              width: 48,
              decoration: BoxDecoration(
                color: blueColor,
                shape: BoxShape.circle,
              ),
              child: Center(
                child: initials.isEmpty
                    ? const FaIcon(
                        FontAwesomeIcons.user,
                        size: 20,
                        color: Colors.white,
                      )
                    : Text(
                        initials,
                        style: const TextStyle(
                          fontSize: 16,
                          fontWeight: FontWeight.bold,
                          color: Colors.white,
                        ),
                      ),
              ),
            ),
            const SizedBox(width: 12),
            Expanded(
              child: Text(
                '$fn $ln',
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: TextStyle(
                  fontSize:
                      MediaQuery.of(context).size.width < 500 ? 16 : 19,
                  fontWeight: FontWeight.bold,
                  color: blueColor,
                ),
              ),
            ),
            const SizedBox(width: 8),

            if (tenant.moveoutDate == null)
              InkWell(
                onTap: () async {
                  // showDialog(
                  //   context: context,
                  //   builder: (BuildContext context) {
                  //     bool isChecked =
                  //         false; // Moved isChecked inside the StatefulBuilder
                  //     return StatefulBuilder(
                  //       builder: (BuildContext context, StateSetter setState) {
                  //         return Dialog(
                  //           backgroundColor: Colors.white,
                  //           surfaceTintColor: Colors.white,
                  //           shape: RoundedRectangleBorder(
                  //               borderRadius: BorderRadius.circular(10.0)),
                  //           child: Padding(
                  //             padding: const EdgeInsets.only(
                  //                 left: 16, right: 16, top: 10, bottom: 10),
                  //             child: Container(
                  //                 // width: MediaQuery.of(context).size.width - 10,
                  //                 width: 900,
                  //                 child: buildMoveout(tenant)),
                  //           ),
                  //         );
                  //       },
                  //     );
                  //   },
                  // );
                  final result = await Navigator.push(
                    context,
                    MaterialPageRoute(
                      builder: (context) => Moveout_properties(
                        properties: widget.properties,
                        moveOutDate: moveOutDate ?? "",
                        leaseId: widget.tenants?.leaseId ?? "",
                        tenant: tenant,
                        tenants: tenants ?? [],
                      ),
                    ),
                  );
                  if (result == true) {
                    setState(() {
                      futureUnitsummery = Properies_summery_Repo()
                          .fetchunit(widget.properties.rentalId ?? "");
                    });
                  }
                },
                child: Row(
                  children: [
                    FaIcon(
                      FontAwesomeIcons.rightFromBracket,
                      size: 17,
                      color: blueColor,
                    ),
                    const SizedBox(width: 5),
                    Text(
                      "Move out",
                      style: TextStyle(
                        fontSize:
                            MediaQuery.of(context).size.width < 500 ? 15 : 15,
                        fontWeight: FontWeight.w500,
                        color: blueColor,
                      ),
                    ),
                  ],
                ),
              ),
            // if (isMoveouts == true)
            if (tenant.moveoutDate != null)
              InkWell(
                onTap: () async {
                  String? tenantId =
                      tenant.tenantId != null && tenant.tenantId!.isNotEmpty
                          ? tenant.tenantId?.first
                          : null;
                  SharedPreferences prefs =
                      await SharedPreferences.getInstance();
                  String? id = prefs.getString("adminId");
                  LeaseMoveoutRepository()
                      .addMoveInTenant(
                    adminId: id!,
                    tenantId: tenantId,
                    leaseId: tenant.leaseId,
                  )
                      .then((value) {
                    setState(() {
                      futurePropertysummery = Properies_summery_Repo()
                          .fetchPropertiessummery(widget.properties.rentalId!);
                      isLoading = false;
                      // isMovedOut = true;
                    });

                    Navigator.pop(context, true);
                  }).catchError((e) {
                    setState(() {
                      isLoading = false;
                    });
                  });
                },
                child: Row(
                  children: [
                    FaIcon(
                      FontAwesomeIcons.circleArrowLeft,
                      size: 17,
                      color: blueColor,
                    ),
                    const SizedBox(width: 5),
                    Text(
                      "Move In",
                      style: TextStyle(
                        fontSize: 14,
                        fontWeight: FontWeight.w500,
                        color: blueColor,
                      ),
                    ),
                  ],
                ),
              ),
            const SizedBox(width: 8),
          ],
        ),
        const SizedBox(height: 20),
        Text(
          '${dateProvider.formatCurrentDate('${tenant.startDate}')} to ${dateProvider.formatCurrentDate('${tenant.endDate}')}',
          style: const TextStyle(
            fontSize: 15,
            color: mutedClr,
            fontWeight: FontWeight.w500,
          ),
        ),
        const SizedBox(height: 14),
        Row(
          children: [
            const FaIcon(
              FontAwesomeIcons.phone,
              size: 16,
              color: mutedClr,
            ),
            const SizedBox(width: 10),
            Expanded(
              child: Text(
                formatPhoneNumber(
                  '${tenant.phoneNumber}',
                ),
                style: const TextStyle(
                  fontSize: 15,
                  color: mutedClr,
                  fontWeight: FontWeight.w500,
                ),
              ),
            ),
          ],
        ),
        const SizedBox(height: 14),
        Row(
          children: [
            const FaIcon(
              FontAwesomeIcons.envelope,
              size: 16,
              color: mutedClr,
            ),
            const SizedBox(width: 10),
            Expanded(
              child: Text(
                '${tenant.email}',
                maxLines: 2,
                style: const TextStyle(
                  fontSize: 15,
                  color: mutedClr,
                  fontWeight: FontWeight.w500,
                ),
              ),
            ),
          ],
        ),
        if (tenant.moveoutDate != null) const SizedBox(height: 10),
        if (tenant.moveoutDate != null)
          Row(
            children: [
              const SizedBox(width: 65),
              Text(
                'Notice Date : ',
                maxLines: 3, // Set maximum number of lines
                overflow:
                    TextOverflow.ellipsis, // Handle overflow with ellipsis
                style: TextStyle(
                    fontSize: 15,
                    color: blueColor,
                    fontWeight: FontWeight.bold),
              ),
              const SizedBox(
                width: 5,
              ),
              Text(
                dateProvider
                    .formatCurrentDate('${tenant.moveoutNoticeGivenDate}'),
                style: TextStyle(
                  fontSize: 15,
                  color: blueColor,
                  fontWeight: FontWeight.w500,
                ),
              ),
            ],
          ),
        if (tenant.moveoutDate != null) const SizedBox(height: 8),
        if (tenant.moveoutDate != null)
          Row(
            children: [
              const SizedBox(width: 65),
              Text(
                'Move out : ',
                maxLines: 3, // Set maximum number of lines
                overflow:
                    TextOverflow.ellipsis, // Handle overflow with ellipsis
                style: TextStyle(
                    fontSize: 15,
                    color: blueColor,
                    fontWeight: FontWeight.bold),
              ),
              const SizedBox(
                width: 5,
              ),
              Text(
                dateProvider.formatCurrentDate('${tenant.moveoutDate}'),
                style: TextStyle(
                  fontSize: 15,
                  color: blueColor,
                  fontWeight: FontWeight.w500,
                ),
              ),
            ],
          ),
        const SizedBox(height: 10),
      ],
      ),
    );
  }

