                            style: ElevatedButton.styleFrom(
                                backgroundColor: blueColor,
                                shape: RoundedRectangleBorder(
                                    borderRadius: BorderRadius.circular(12.0))),
                            onPressed: () async {
                              if (deleting) return;
                              deleting = true;
                              // The repository toasts the server's own reason
                              // and then throws when the delete is rejected.
                              // Nothing caught it, so the exception escaped
                              // into the framework with no explanation; the
                              // message has already been shown.
                              try {
                                var data = await Properies_summery_Repo()
                                    .Deleteunit(unitId: unit?.unitId!);
                                if (!mounted) return;
                                // Only refresh when the delete actually
                                // succeeded.
                                setState(() {
                                  futureUnitsummery = Properies_summery_Repo()
                                      .fetchunit(widget.properties.rentalId!);
                                  showdetails = false;
                                  // Update unit count after deletion
                                  unitCount = unitCount > 0 ? unitCount - 1 : 0;
                                });
                              } catch (_) {
                                deleting = false;
                              }
                              //Navigator.pop(context);
                            },
                            child: Text(
                              'Delete unit',
                              style: TextStyle(
                                  fontSize:
