  }

  Widget _buildPropertyValueTable(Rentals rentalDetails) {
    final list = rentalDetails.propertyValues ?? [];
    final dateProvider = Provider.of<DateProvider>(context, listen: false);
    return Padding(
      padding: const EdgeInsets.only(left: 2.0),
      child: Container(
