  String _formatSource(String? s) {
    if (s == null || s.isEmpty) return '—';
    switch (s.toLowerCase()) {
      case 'manual':
        return 'Manual';
      case 'zillow':
        return 'Zillow';
      case 'appraisal':
        return 'Appraisal';
      case 'other':
        return 'Other';
      default:
        return s;
    }
  }

