                                  children: [
                                    _buildHeader('Status', 0,
                                        (rental) => rental.startDate!),
                                    _buildHeader('Start-End', 1,
                                        (rental) => rental.endDate!),
                                    _buildHeader('Tenant', 2,
                                        (rental) => rental.tenantFirstName!),
                                    _buildHeader('Type', 3,
